function chain(n) {
  let s = "";
  let cur = n, depth = 0;
  while (cur && depth < 12) {
    s += cur.id + "[" + cur.type + " " + cur.name + "] <- ";
    cur = cur.parent;
    depth++;
  }
  return s;
}
