function dump(n, d, maxd) {
  if (!n || d > maxd) return "";
  let f = "?";
  try { f = JSON.stringify(n.fills); } catch(e) { f = "err"; }
  let s = "  ".repeat(d) + n.id + " " + n.type + " '" + n.name + "' " + Math.round(n.width*10)/10 + "x" + Math.round(n.height*10)/10 + " @(" + Math.round(n.x*10)/10 + "," + Math.round(n.y*10)/10 + ") fills=" + f;
  try { if (n.strokes && n.strokes.length) s += " strokes=" + JSON.stringify(n.strokes); } catch(e) {}
  try { if (n.type === "TEXT") s += " font=" + n.fontName.style + " sz=" + n.fontSize + " txt='" + n.characters + "'"; } catch(e) {}
  try { if ("cornerRadius" in n && n.cornerRadius !== 0) s += " r=" + n.cornerRadius; } catch(e) {}
  try { if (n.visible === false) s += " HIDDEN"; } catch(e) {}
  s += "\n";
  if (n.children) { for (const c of n.children) s += dump(c, d+1, maxd); }
  return s;
}
