function inst(id,parent,x,y){const i=figma.getNodeById(id).createInstance();parent.appendChild(i);i.x=x;i.y=y;return i;}
function recolor(i,hex){const kids=i.children||[];for(const c of kids){if(Array.isArray(c.fills)&&c.fills.length&&c.fills!==figma.mixed)c.fills=[P(hex)];if(Array.isArray(c.strokes)&&c.strokes.length)c.strokes=[P(hex)];}}
